 if(status){const ch=c.findOne(n=>n.name==='Chip');ch.resize(Math.max(90,status.length*7+16),20);const ct=ch.findOne(n=>n.name==='ChipText');ct.characters=status;if(status==='Unavailable')ct.fills=[solid('#757575')];}
 else{c.findOne(n=>n.name==='Chip').visible=false;}
 c.findOne(n=>n.name==='Name').characters=name;
 c.findOne(n=>n.name==='Type').characters=type;
 c.findOne(n=>n.name==='Price').characters=price;return c;}
