const byName={}; page.children.forEach(c=>{if(c.type==='FRAME')byName[c.name]=c;});
const N=(f,name)=>f.findOne(n=>n.name===name);
function link(node,destName){const dest=byName[destName];if(!node||!dest)return false;
 node.reactions=[{trigger:{type:'CLICK'},action:{type:'NODE',destinationId:dest.id,navigation:'NAVIGATE',transition:{type:'INSTANT'}}}];return true;}
let bad=[];
const L=(fname,nodeName,dest)=>{if(!link(N(byName[fname],nodeName),dest))bad.push(fname+'.'+nodeName+'→'+dest);};
